%[text] # SG visualization
%[text] 20251212  y.yoshimura
%[text] (c) 2022 yasuhiro yoshimura
clc
clear
cls
%[text] ## object parameters
phi = 0:deg2rad(1):2*pi;
theta = 0:deg2rad(1):pi/2;
%[text] ## illumination condition
azi = 0:deg2rad(2):2*pi;
ele = 0:deg2rad(2):pi;
[phiR, thetaR] = meshgrid(azi, ele);

x = cos(phiR) .* sin(thetaR);
y = sin(phiR) .* sin(thetaR);
z = cos(thetaR);

p1 = [0; 0; 1];
lam1 = 0.5;
mu1 = 1;

p2 = [1; 1; 0];
p2 = p2 ./ norm(p2);
lam2 = 0.3;
mu2 = 1;

sg1 = sg(x, y, z, p1, lam1, mu1);

%%
%[text] ## show figs
%[text] on sphere
l = 1.5; % arrow scale

figure %[output:237281ce]
figSurf = surf(x, y, z, sg1, 'edgecolor', 'none') %[output:45edce1f] %[output:237281ce]
% colorbar
% alpha 0.4
axis equal %[output:237281ce]
hold on %[output:237281ce]
quiver3(0,0,0, l*p1(1), l*p1(2), l*p1(3), 'r') %[output:237281ce]
quiver3(0,0,0, l*p2(1), l*p2(2), l*p2(3), 'r') %[output:237281ce]
xlabel('x'), ylabel('y'), zlabel('z') %[output:237281ce]
view([124.61 34.81]) %[output:237281ce]

% figure
% contourf(cos(phiR).*sin(thetaR), sin(phiR).*sin(thetaR), D);
% hold on
% plot(vNominal(1), vNominal(2), 'yx')
% colorbar
% axis equal
% xlabel('x'), ylabel('y')


